for(const view of['original','reverse'])test(`copier keeps horizontal footprint, lowered output and animated hand-held paper contact (${view})`,async()=>{const f=await fixture(root,view),m=f.bumperGroups.copier.getObjectByName('mechanism');assert.equal(m.scale.x,2.755);assert.equal(m.scale.z,2.755);assert.ok(Math.abs(m.scale.y-2.755*.85)<1e-8);const tray=m.getObjectByName('copierTray'),paper=m.getObjectByName('copierOutputPaper');assert.ok(tray&&paper);assert.ok(Math.abs(paper.getWorldPosition(new f.T.Vector3()).y-1.7)<1e-8);const angles=[];for(let n=0;n<60;n++){const p=f.createCharacter();const station=f.BUMPERS.find(o=>o.id==='copier'),dock=f.dockFor(station,view);p.position.set(-(dock.x-station.x),1.34,dock.z-station.z);p.rotation.y=Math.PI+f.stageYaw(view);f.poseCharacter(p,{activity:'copier',time:n/20,progress:n/60});p.updateMatrixWorld(true);const hand=p.userData.rig.left.hand.getWorldPosition(new f.T.Vector3()),sheet=p.userData.rig.paper,body=p.userData.rig.body;angles.push(p.userData.rig.left.shoulder.rotation.x);assert.ok(Math.abs(hand.y-1.7)<.06,`hand y ${hand.y}`);const sheetBounds=f.bounds(sheet),outBounds=f.bounds(paper);assert.ok(sheetBounds.intersectsBox(outBounds),'hand sheet overlaps output paper to avoid detached pulling');assert.ok(sheetBounds.getSize(new f.T.Vector3()).y<.04,'held paper stays horizontal');assert.equal(body.rotation.x,-.12);}assert.ok(Math.max(...angles)-Math.min(...angles)>.05,'retain visible small pull motion');});
