for(const [w,h]of[[1440,900],[390,844],[844,390]])for(const view of['original','reverse'])test(`work camera frames revised equipment and actor in ${view} ${w}x${h}`,async()=>{const f=await fixture(root,view),{StableRig,SLOPE}=await import(new URL('../../public/games/overtime-pinball/camera.js',import.meta.url));for(const id of ['chair','copier','desk','launcher','desk2','shredder','water']){const o=f.BUMPERS.find(o=>o.id===id),g=f.bumperGroups[id];g.position.set(-o.x,0,o.z);f.office.rotation.x=SLOPE;const dock=f.dockFor(o,view),interaction={stage:'work',stationId:id,activity:id==='desk'?'busy':id==='desk2'?'coffee':id,dock,from:dock},rig=new StableRig(view);let pose;for(let n=0;n<180;n++)pose=rig.update(1/60,w,h,dock,interaction,o,false,{portrait:w<h});const camera=new f.T.PerspectiveCamera(pose.fov,w/h,.1,500);camera.position.set(...pose.position);camera.lookAt(new f.T.Vector3(...pose.target));camera.updateMatrixWorld();const actor=f.createCharacter(),cp=id==='chair'?helpers.chairRenderPose(o.visualScale,'work'):null;actor.position.set(-dock.x-(cp?Math.sin(f.stageYaw(view))*cp.forward:id==='desk'?Math.sin(Math.PI+f.stageYaw(view))*helpers.busyRenderForward('work'):0),cp?cp.y:id==='desk'?helpers.busyRenderHeight(o.visualScale,'work'):id==='launcher'?helpers.launcherRenderHeight(1,'work'):id==='desk2'?helpers.coffeeRenderHeight('work'):1.34,dock.z-(cp?Math.cos(f.stageYaw(view))*cp.forward:id==='desk'?Math.cos(Math.PI+f.stageYaw(view))*helpers.busyRenderForward('work'):0));actor.rotation.y=(id==='chair'?0:Math.PI)+f.stageYaw(view);f.poseCharacter(actor,{activity:id==='desk'?'busy':id==='desk2'?'coffee':id,time:0});f.office.add(actor);f.office.updateMatrixWorld(true);for(const object of [g,actor]){const bounds=f.bounds(object,true);for(const x of[bounds.min.x,bounds.max.x])for(const y of[bounds.min.y,bounds.max.y])for(const z of[bounds.min.z,bounds.max.z]){const v=new f.T.Vector3(x,y,z).project(camera);assert.ok(v.toArray().every(Number.isFinite));assert.ok(Math.abs(v.x)<=1.05&&Math.abs(v.y)<=1.05&&v.z>=-1&&v.z<=1,`${id} ${object===actor?'actor':'equipment'} projected ${v.toArray()}`);}}f.office.remove(actor);g.position.set(0,0,0);}});
