for(const view of ['original','reverse'])for(const id of ['chair','desk','launcher'])test(`actual Game docking/launch preserves readable surface clearance ${id}/${view}`,async()=>{const f=await fixture(root,view),station=f.BUMPERS.find(o=>o.id===id),g=new Game({view,patrol:false});g.start();const dock=f.dockFor(station,view);Object.assign(g.ball,{x:dock.x+3,z:dock.z-3});assert.ok(g.startInteraction(station,'left',false));const person=f.createCharacter(),stageCounts={docking:0,work:0,launch:0};let launchChecks=0;for(let n=0;n<1200&&g.interaction;n++){g.updateInteraction(1/120,{});const i=g.interaction;if(!i)break;stageCounts[i.stage]++;const a=i.activity,cp=a==='chair'?helpers.chairRenderPose(station.visualScale,i.stage,i.elapsed,i.dockDuration,i.launchElapsed):null,rootY=cp?cp.y:a==='busy'?helpers.busyRenderHeight(station.visualScale,i.stage,i.elapsed,i.dockDuration,i.launchElapsed):helpers.launcherRenderHeight(i.elapsed,i.stage,i.dockDuration,i.launchElapsed),yaw=(a==='chair'?i.spinAngle:Math.PI)+f.stageYaw(view);person.position.set(-(g.ball.x-station.x)-(cp?Math.sin(yaw)*cp.forward:0),rootY+g.hop,g.ball.z-station.z-(cp?Math.cos(yaw)*cp.forward:0));person.rotation.y=yaw;if(a==='busy'){const forward=helpers.busyRenderForward(i.stage,i.elapsed,i.dockDuration,i.launchElapsed);person.position.x-=Math.sin(yaw)*forward;person.position.z-=Math.cos(yaw)*forward;}f.poseCharacter(person,{activity:['docking','launch'].includes(i.stage)?'flight':a,time:i.elapsed,progress:0});person.updateMatrixWorld(true);const ballBefore=JSON.stringify(g.ball);if(id==='launcher')helpers.keepLauncherFeetAboveSurface(person,f.assistOffice.models.center.root,Math.min(1,i.elapsed/.35)*1.2);assert.equal(JSON.stringify(g.ball),ballBefore);person.updateMatrixWorld(true);assert.ok(person.position.toArray().every(Number.isFinite));if(id==='launcher'){const inv=f.assistOffice.models.center.root.matrixWorld.clone().invert(),lift=Math.min(1,i.elapsed/.35)*1.2;for(const side of ['left','right']){const shoe=person.getObjectByName(side+'Shoe');shoe.geometry.computeBoundingBox();const b=shoe.geometry.boundingBox;for(const x of[b.min.x*1.035,b.max.x*1.035])for(const y of[b.min.y*1.035,b.max.y*1.035])for(const z of[b.min.z*1.035,b.max.z*1.035]){const v=new f.T.Vector3(x,y,z).applyMatrix4(shoe.matrixWorld).applyMatrix4(inv),paper=Math.abs(v.x)<=.45&&Math.abs(v.z)<=.325,disc=Math.hypot(v.x,v.z)<=2.3;if(paper||disc)assert.ok(v.y>=(paper?.49:.22)+lift-.001,`${i.stage} surface crossing ${v.toArray()}`);}}}if(i.stage==='launch'){launchChecks++;assert.ok(i.launchRoute&&i.release,'actual solver creates launch route');if(id==='launcher'){const inv=f.assistOffice.models.center.root.matrixWorld.clone().invert();for(const side of ['left','right']){const shoe=person.getObjectByName(side+'Shoe');shoe.geometry.computeBoundingBox();const b=shoe.geometry.boundingBox.clone();b.min.multiplyScalar(1.035);b.max.multiplyScalar(1.035);for(const x of[b.min.x,b.max.x])for(const y of[b.min.y,b.max.y])for(const z of[b.min.z,b.max.z]){const p=new f.T.Vector3(x,y,z).applyMatrix4(shoe.matrixWorld).applyMatrix4(inv);if(Math.abs(p.x)<=.45&&Math.abs(p.z)<=.325)assert.ok(p.y>=1.69-.001,`launch foot crosses paper ${p.toArray()} t${i.launchElapsed}`);}}}}}assert.ok(stageCounts.docking>0&&stageCounts.work>0&&launchChecks>20,JSON.stringify(stageCounts));});
